def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The 2x2 zero marker defines two full rows and columns to erase,
    # while the marked horizontal rows retain the distinguishing color 2.
    for r in range(h - 1):
        for c in range(w - 1):
            if all(g[rr][cc] == 0 for rr in (r, r + 1) for cc in (c, c + 1)):
                for rr in range(h):
                    for cc in (c, c + 1):
                        if g[rr][cc] != 2:
                            g[rr][cc] = 0
                for rr in (r, r + 1):
                    for cc in range(w):
                        if g[rr][cc] != 2:
                            g[rr][cc] = 0
                return g
    return g

